import OpenAI from "openai"; const client = new OpenAI({ baseURL: "{{BASE_URL}}", apiKey: "{{API_KEY}}" }); const stream = await client.chat.completions.create({ messages: [{ role: "user", content: "hello" }], stream: true, });
for await (const chunk of stream) { process.stdout.write(chunk.choices[0]?.delta?.content ?? "");
}

